function saveRecordDetail(id){const r=appData.records.find(x=>x.id==id||String(x.id)===String(id));if(!r){showToast('❌ 找不到这条记录（id='+id+'）');return;}
r.taskName=document.getElementById('detailTaskName').value.trim()||'未命名任务';r.note=document.getElementById('detailNote').value.trim();const se=getGridValue('detailStartEnergyPicker');const sm=getGridValue('detailStartMoodPicker');r.startEnergy=se||null;r.startMood=sm||null;const e=getGridValue('detailEndEnergyPicker');const m=getGridValue('detailEndMoodPicker');r.energy=e||null;r.mood=m||null;const _typeSel=document.getElementById('detailRecordType');if(_typeSel&&_typeSel.value&&_typeSel.value!==r.type){const _oldType=r.type;const _oldPomos=getPomos(r);r.type=_typeSel.value;r.pomos=calcPomos(r.effectiveSeconds||0,r.type);adjustRecordRewards(r,_oldType,_oldPomos);updateTodayStats();updateRoundStats();}
const _planSel=document.getElementById('detailPlanId');if(_planSel){const v=String(_planSel.value||'');const oldId=r.todoId!=null?String(r.todoId):'';if(v!==oldId){const t=findTodoByIdStr(v);r.todoId=t?t.id:null;r.tag=t&&t.tag?t.tag:null;r.quad=t?normQuad(t.quad):null;r.planTitle=t?t.title||null:null;r.planSubs=t?snapshotPlanSubs(t,r.endTime):null;r.subTitle=null;r.subId=null;}}
touchRecord(r);saveData();invalidateStatsCache();renderLogs();closeModal('recordDetailModal');showToast('✅ 已保存');}
function fillAddRecordTimeOptions(now){const hSel=document.getElementById('addRecordHour');const mSel=document.getElementById('addRecordMinute');if(!hSel||!mSel)return;hSel.innerHTML='';for(let i=0;i<24;i++){const o=document.createElement('option');o.value=String(i).padStart(2,'0');o.textContent=String(i).padStart(2,'0');hSel.appendChild(o);}
mSel.innerHTML='';for(let i=0;i<60;i++){const o=document.createElement('option');o.value=String(i).padStart(2,'0');o.textContent=String(i).padStart(2,'0');mSel.appendChild(o);}
hSel.value=String(now.getHours()).padStart(2,'0');mSel.value=String(now.getMinutes()).padStart(2,'0');}
