function buildDiaryForm(date,prefix){const d=ensureDiary(date);let countdownHtml='';const sorted=[...appData.countdowns].sort(_cdSort);if(sorted.length>0){const pins=sorted.filter(_isPinned);const nearest=pins.length?pins[0]:null;const days=nearest?getDaysUntil(nearest.date):0;const text=nearest?days===0?`今天就是'${escapeHtml(nearest.title)}'！`:`距离'${escapeHtml(nearest.title)}'还有 ${days} 天`:'';const color=days===0?'var(--danger)':'var(--text-light)';const dropdownItems=sorted.map(c=>{const cd=getDaysUntil(c.date);const ct=cd===0?`今天就是'${escapeHtml(c.title)}'！`:`距离'${escapeHtml(c.title)}'还有 ${cd} 天`;return`<div style="padding:var(--sp-8) var(--sp-12);border-bottom:1px solid var(--border);cursor:pointer;font-size:var(--fs-title);" onclick="event.stopPropagation();openCountdownDetail(${idArg(c.id)});document.getElementById('diaryCountdownDropdown').style.display='none';">${escapeHtml(c.icon || '📌')} ${ct}${_isPinned(c) ? ' <span style="font-size:var(--fs-caption);color:var(--text-light);">📌</span>' : ''}</div>`;}).join('');const cdHeadLine=nearest?`<div style="background:var(--bg);border:1px dashed var(--yellow);border-radius:var(--radius-sm);padding:var(--sp-8) var(--sp-12);font-size:var(--fs-title);color:${color};font-weight:600;cursor:pointer;" onclick="toggleDiaryCountdown()">${escapeHtml(nearest.icon || '📌')} ${text} <span style="float:right;">▾</span></div>`:`<div style="background:var(--bg);border:1px solid var(--hairline);border-radius:var(--radius-sm);padding:var(--sp-8) var(--sp-12);font-size:var(--fs-title);color:var(--text-light);cursor:pointer;" onclick="toggleDiaryCountdown()">📌 倒数日 · 全部 ${sorted.length} 个 <span style="float:right;">▾</span></div>`;countdownHtml=`<div style="margin-bottom:var(--sp-12);">${cdHeadLine}<div id="diaryCountdownDropdown" style="display:none;background:var(--card);border:1px solid var(--border);border-radius:var(--radius-sm);margin-top:var(--sp-4);overflow:hidden;">${dropdownItems}</div></div>`;}
const yd=new Date(date+'T00:00:00');yd.setDate(yd.getDate()-1);const yds=getDateStr(yd);const yesterdayImprove=((appData.diaries[yds]&&appData.diaries[yds].review&&appData.diaries[yds].review.improvements)||'');const yesterdayHtml=yesterdayImprove?`<div class="settings-group" style="margin-bottom:var(--sp-10);background:var(--bg);border:3px solid var(--border);"><h3 style="color:var(--blue-dark);">📌 昨日待改进</h3><div style="font-size:var(--fs-title);color:var(--text);padding:var(--sp-8);background:var(--card);border-radius:var(--radius-xs);line-height:1.6;">${escapeHtml(yesterdayImprove)}</div></div>`:'';const _fb=d.feedback||{};const _fbBits=[];if(_fb.sleepTime)_fbBits.push('睡 '+escapeHtml(_fb.sleepTime));if(_fb.wakeTime)_fbBits.push('醒 '+escapeHtml(_fb.wakeTime));if(_fb.sleepQuality)_fbBits.push('睡眠 '+escapeHtml(String(_fb.sleepQuality)));if(_fb.mentalState)_fbBits.push('精神 '+escapeHtml(String(_fb.mentalState)));const fbSummary=_fbBits.length?_fbBits.join(' · '):'还没填';const _gr=(d.gratitude&&Array.isArray(d.gratitude.items))?d.gratitude.items:[];let gratitudeGroup='';for(let gi=0;gi<3;gi++){gratitudeGroup+='<div class="gratitude-row"><span class="gr-i">'+(gi+1)+'</span>'+'<input type="text" id="'+prefix+'_gr_'+gi+'_'+date+'" maxlength="200"'+' placeholder="第 '+(gi+1)+' 件…" value="'+escapeHtml(_gr[gi]||'')+'"'+' oninput="scheduleDiaryAutoSave(\''+date+'\')"></div>';}
gratitudeGroup='<div class="settings-group" style="margin-bottom:var(--sp-10);"><h3>🙏 感恩日记</h3>'+'<div style="font-size:var(--fs-note);color:var(--text-light);margin-bottom:var(--sp-8);">今天有哪几件小事值得感谢？写不满也没关系，一件就够。</div>'+
gratitudeGroup+'</div>';const _roOpen=!!(d.review.other&&String(d.review.other).trim());const _revFields=`<div class="diary-field"><label>今天进步</label><textarea id="${prefix}_rp_${date}" placeholder="写一件做成的、哪怕很小的事" oninput="scheduleDiaryAutoSave('${date}');diaryAutoGrow(this)">${escapeHtml(d.review.progress || '')}</textarea></div>`+`<div class="diary-field"><label>今天不足</label><textarea id="${prefix}_rs_${date}" placeholder="今天卡在哪、被打断了几次" oninput="scheduleDiaryAutoSave('${date}');diaryAutoGrow(this)">${escapeHtml(d.review.shortcomings || '')}</textarea></div>`+`<div class="diary-field"><label>明天改进</label><textarea id="${prefix}_ri_${date}" placeholder="明天只改一件" oninput="scheduleDiaryAutoSave('${date}');diaryAutoGrow(this)">${escapeHtml(d.review.improvements || '')}</textarea></div>`+`<div class="diary-field"><label>该停止</label><input type="text" id="${prefix}_rst_${date}" maxlength="120" placeholder="今天最该戒掉的一件事（可选）" oninput="scheduleDiaryAutoSave('${date}')" value="${escapeHtml(d.review.stop || '')}"></div>`+`<div class="diary-subfold"><div class="diary-fold-head${_roOpen ? ' open' : ''}" onclick="toggleDiaryFoldHead(this)"><span>其他记录</span><span class="dfh-arrow">▸</span></div><div class="diary-fold-body" style="display:${_roOpen ? 'block' : 'none'}"><div class="diary-field"><textarea id="${prefix}_ro_${date}" placeholder="想记的杂事、情绪、想法…" oninput="scheduleDiaryAutoSave('${date}');diaryAutoGrow(this)">${escapeHtml(d.review.other || '')}</textarea></div></div></div>`;const _fbOpen=true;return`${countdownHtml}${yesterdayHtml}<div class="settings-group" style="margin-bottom:var(--sp-10);"><h3>🔍 每日复盘</h3>${_revFields}</div>${gratitudeGroup}<div class="settings-group" style="margin-bottom:var(--sp-10);"><div class="diary-fold-head${_fbOpen ? ' open' : ''}" onclick="toggleDiaryFoldHead(this)"><h3 style="margin:0">😴 今日反馈<span style="font-size:var(--fs-caption);font-weight:400;color:var(--text-light);margin-left:var(--sp-6)">${fbSummary}</span></h3><span class="dfh-arrow">▸</span></div><div class="diary-fold-body" style="display:${_fbOpen ? 'block' : 'none'}"><div class="diary-row"><div class="diary-field"><label>昨晚入睡</label><div style="display:flex;gap:var(--sp-6);align-items:center;"><select id="${prefix}_fsd_${date}" onchange="scheduleDiaryAutoSave('${date}')" style="flex:1;min-width:0;padding:var(--sp-8);border:1px solid var(--border-strong);border-radius:var(--radius-sm);font-size:var(--fs-body);background:var(--card);color:var(--text);"><option value="prev" ${(d.feedback.sleepDay || 'prev') === 'prev' ? 'selected' : ''}>昨晚</option><option value="today" ${(d.feedback.sleepDay || 'prev') === 'today' ? 'selected' : ''}>今天凌晨</option></select><input type="time" id="${prefix}_fs_${date}" value="${d.feedback.sleepTime || ''}" onchange="scheduleDiaryAutoSave('${date}')" style="flex:1.2;min-width:0;"></div><div style="font-size:var(--fs-tiny);color:var(--text-light);margin-top:var(--sp-2);">昨晚 23:30 睡选「昨晚」；拖到凌晨 1 点才睡选「今天凌晨」</div></div><div class="diary-field"><label>起床时间</label><input type="time" id="${prefix}_fw_${date}" value="${d.feedback.wakeTime || ''}" onchange="scheduleDiaryAutoSave('${date}')"></div></div><div class="diary-field"><label>睡眠质量</label><div class="grid-picker" id="${prefix}_fq_${date}_grid"></div><span id="${prefix}_fq_${date}_label" style="margin-left:var(--sp-8);font-size:var(--fs-body);font-weight:800;color:var(--blue-dark);"></span></div><div class="diary-field"><label>精神状态</label><div class="grid-picker" id="${prefix}_fe_${date}_grid"></div><span id="${prefix}_fe_${date}_label" style="margin-left:var(--sp-8);font-size:var(--fs-body);font-weight:800;color: var(--yellow-ink);"></span></div></div></div><button class="save-btn" onclick="forceSaveDiary('${date}');showToast('✅保存成功')">💾 立即保存</button>`;}
function renderDiarySingle(){const view=document.getElementById('diarySingleView');const today=getTodayStr();if(!currentDiaryDate)currentDiaryDate=today;const isToday=currentDiaryDate===today;try{if(typeof renderLogReviewBar==='function')renderLogReviewBar();}catch(e){if(window.__silent)window.__silent(e,'01e:reviewBar');}
renderDailyFocusSummary(currentDiaryDate);renderBioSection();view.innerHTML=`<div class="diary-current-date">📅 ${currentDiaryDate}${isToday ? '（今天）' : ''}<button class="btn-small" style="margin-left:var(--sp-8);" onclick="openCalendarModal()">选择日期</button></div>${buildDiaryForm(currentDiaryDate, 'single')}`;initDiaryGrids('single',currentDiaryDate);diaryAutoGrowAll('single',currentDiaryDate);}
function initDiaryGrids(prefix,date){const fq=document.getElementById(prefix+'_fq_'+date+'_grid');const fe=document.getElementById(prefix+'_fe_'+date+'_grid');if(fq){const d=ensureDiary(date);renderGridPicker(fq.id,d.feedback.sleepQuality?parseInt(d.feedback.sleepQuality):null,'blue');fq.querySelectorAll('.grid-cell').forEach(cell=>{cell.onclick=()=>{setGridValue(fq.id,parseInt(cell.dataset.val));scheduleDiaryAutoSave(date);};});}
if(fe){const d=ensureDiary(date);renderGridPicker(fe.id,d.feedback.mentalState?parseInt(d.feedback.mentalState):null,'yellow');fe.querySelectorAll('.grid-cell').forEach(cell=>{cell.onclick=()=>{setGridValue(fe.id,parseInt(cell.dataset.val));scheduleDiaryAutoSave(date);};});}}
function scheduleDiaryAutoSave(date){if(diaryAutoSaveTimers[date])clearTimeout(diaryAutoSaveTimers[date]);diaryAutoSaveTimers[date]=setTimeout(()=>{forceSaveDiary(date);showAutoSaveHint();},5000);}
function forceSaveDiary(date){if(diaryAutoSaveTimers[date]){clearTimeout(diaryAutoSaveTimers[date]);diaryAutoSaveTimers[date]=null;}
const d=ensureDiary(date);const planEl=document.getElementById('single_plan_'+date);if(planEl)d.plan=planEl.value;const rp=document.getElementById('single_rp_'+date);if(rp)d.review.progress=rp.value;const rs=document.getElementById('single_rs_'+date);if(rs)d.review.shortcomings=rs.value;const ri=document.getElementById('single_ri_'+date);if(ri)d.review.improvements=ri.value;const rst=document.getElementById('single_rst_'+date);if(rst)d.review.stop=rst.value;const ro=document.getElementById('single_ro_'+date);if(ro)d.review.other=ro.value;const fs=document.getElementById('single_fs_'+date);if(fs)d.feedback.sleepTime=fs.value;const fsd=document.getElementById('single_fsd_'+date);if(fsd)d.feedback.sleepDay=fsd.value;const fw=document.getElementById('single_fw_'+date);if(fw)d.feedback.wakeTime=fw.value;const fq=document.getElementById('single_fq_'+date+'_grid');if(fq)d.feedback.sleepQuality=getGridValue(fq.id)||'';const fe=document.getElementById('single_fe_'+date+'_grid');if(fe)d.feedback.mentalState=getGridValue(fe.id)||'';const grItems=[];for(let gi=0;gi<3;gi++){const ge=document.getElementById('single_gr_'+gi+'_'+date);if(!ge)continue;const gv=String(ge.value||'').trim().slice(0,200);if(gv)grItems.push(gv);}
if(grItems.length)d.gratitude={items:grItems};else delete d.gratitude;const hasContent=d.plan||d.review.progress||d.review.shortcomings||d.review.improvements||d.review.other||d.feedback.sleepTime||d.feedback.wakeTime||d.feedback.sleepQuality||d.feedback.mentalState||grItems.length;if(hasContent){appData.diaries[date]=d;}else if(appData.diaries[date]&&!hasContent){delete appData.diaries[date];}
saveData();}
let _calendarPick=null;function openCalendarModal(opts){_calendarPick=(opts&&typeof opts.onPick==='function')?opts:null;const now=new Date();__set_calendarYear(now.getFullYear());__set_calendarMonth(now.getMonth());const _s=document.getElementById('calendarSearch');if(_s)_s.value='';const _sr=document.getElementById('calendarSearchResults');if(_sr)_sr.innerHTML='';if(_s)_s.style.display=_calendarPick?'none':'';const _jrow=document.getElementById('calendarJumpRow');if(_jrow)_jrow.style.display='none';renderCalendar();showModal('calendarModal');}
function renderCalendar(){document.getElementById('calendarTitle').textContent=calendarYear+'年'+(calendarMonth+1)+'月';const _jy=document.getElementById('calendarJumpYear');if(_jy)_jy.textContent=calendarYear;const _jm=document.getElementById('calendarJumpMonths');if(_jm){if(!_jm.childNodes.length){let mh='<span class="cal-jump-lbl">月</span>';for(let m=1;m<=12;m++)mh+='<button class="cal-jump-m" data-m="'+m+'" onclick="jumpCalendarMonth('+m+')">'+m+'</button>';_jm.innerHTML=mh;}
Array.prototype.forEach.call(_jm.querySelectorAll('.cal-jump-m'),function(b){b.classList.toggle('on',Number(b.getAttribute('data-m'))===calendarMonth+1);});}
const grid=document.getElementById('calendarGrid');const weekdays=['日','一','二','三','四','五','六'];let html=weekdays.map(w=>`<div class="calendar-weekday">${w}</div>`).join('');const firstDay=new Date(calendarYear,calendarMonth,1).getDay();const daysInMonth=new Date(calendarYear,calendarMonth+1,0).getDate();const today=getTodayStr();const todayDate=new Date();const pick=_calendarPick;for(let i=0;i<firstDay;i++){html+='<div class="calendar-day empty"></div>';}
for(let day=1;day<=daysInMonth;day++){const dateStr=calendarYear+'-'+String(calendarMonth+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const marked=pick?(typeof pick.mark==='function'?!!pick.mark(dateStr):false):!!appData.diaries[dateStr];const isToday=dateStr===today;const isFuture=!pick&&new Date(dateStr)>new Date(todayDate.getFullYear(),todayDate.getMonth(),todayDate.getDate());let cls='calendar-day';if(marked)cls+=' has-diary';if(isToday)cls+=' today';if(isFuture)cls+=' disabled';const onclick=!isFuture?`onclick="calendarDayPick('${dateStr}')"`:'';html+=`<div class="${cls}" ${onclick}>${day}</div>`;}
grid.innerHTML=html;}
function openCalendarJump(){const row=document.getElementById('calendarJumpRow');if(!row)return;row.style.display=row.style.display==='none'?'block':'none';}
function changeCalendarYear(delta){calendarYear+=Number(delta)||0;renderCalendar();}
function jumpCalendarMonth(m){const mm=Math.max(1,Math.min(12,Number(m)||1))-1;__set_calendarMonth(mm);renderCalendar();}
function changeCalendarMonth(delta){calendarMonth+=Number(delta)||0;if(calendarMonth<0){__set_calendarMonth(11);calendarYear--;}
if(calendarMonth>11){__set_calendarMonth(0);calendarYear++;}
renderCalendar();}
function calendarDayPick(date){if(_calendarPick){const h=_calendarPick.onPick;_calendarPick=null;closeModal('calendarModal');h(date);return;}
selectDiaryDate(date);}
function selectDiaryDate(date){forceSaveDiary(currentDiaryDate);__set_currentDiaryDate(date);closeModal('calendarModal');switchLogTab('diary');renderDiarySingle();}
function goToTodayDiary(){calendarDayPick(getTodayStr());}
function searchDiaries(keyword){const kw=keyword.trim().toLowerCase();const results=document.getElementById('calendarSearchResults');if(!kw){results.innerHTML='';return;}
const matches=[];Object.keys(appData.diaries).forEach(date=>{const d=appData.diaries[date];const text=[d.plan,d.review&&d.review.progress,d.review&&d.review.shortcomings,d.review&&d.review.improvements,d.review&&d.review.other].join(' ').toLowerCase();if(text.includes(kw)){const snippet=((d.review&&d.review.progress)||d.plan||'').substring(0,40);matches.push({date,snippet});}});matches.sort((a,b)=>b.date.localeCompare(a.date));if(!matches.length){results.innerHTML='<div style="text-align:center;color:var(--text-light);padding:var(--sp-10);font-size:var(--fs-title);">未找到匹配的日记</div>';return;}
results.innerHTML=matches.map(m=>`<div class="calendar-search-item" onclick="selectDiaryDate('${m.date}')"><div class="sr-date">${m.date}</div><div class="sr-snippet">${escapeHtml(m.snippet)}…</div></div>`).join('');}
function renderWeeklyBadges(){const container=document.getElementById('weeklyBadgeList');if(!container)return;const weekDone=getWeekTomatoPoints();const currentWeekCount=getWeekHeldTomatoes();const wcEl=document.getElementById('weekTomatoCount');if(wcEl)wcEl.textContent=fmtTomatoNum(weekDone);const whEl=document.getElementById('weekTomatoHeld');if(whEl){whEl.textContent=fmtTomatoNum(currentWeekCount);whEl.style.color=currentWeekCount>0?'var(--green)':'var(--red,#C0392B)';}
container.innerHTML=WEEKLY_BADGES.map(b=>{const cumulative=((appData.weeklyBadges&&appData.weeklyBadges.cumulative&&appData.weeklyBadges.cumulative[b.id])||0);const habitMet=!b.habitReq||checkWeekHabitReq(getWeekStartStr(),b.habitReq);const state=getBadgeState(b);const lit=state!=='off';let progressHint='';if(!lit){if(b.habitReq&&currentWeekCount>=b.goal){const miss=weekHabitMissingDays(b.habitReq);progressHint='还差 习惯打卡（'+(miss>0?miss+'天':'')+'）';}else if(currentWeekCount<b.goal){progressHint='还差 '+Math.max(1,Math.ceil(b.goal-currentWeekCount))+' 🍅';}}
const gloryClass=b.glow&&lit?' badge-glory':'';const habitHtml=b.habitReq?`<div style="font-size:var(--fs-title);color:${habitMet ? 'var(--green)' : 'var(--primary)'};margin-top:var(--sp-2);">🌿${b.habitReqDesc}</div>`:'';const stateText=state==='this'?'✅ 本周达成':state==='carry'?'⏳ 延续中·本周需再达成':'熄灭';const stateColor=state==='this'?'var(--green)':state==='carry'?'var(--yellow-dark)':'#999';return`<div class="badge-card${gloryClass}" style="text-align:center;padding:var(--sp-10) var(--sp-6);width:82px;border:2px solid ${lit ? b.color : '#ddd'};border-radius:var(--radius);background:${lit ? b.bg : '#f9f9f9'};opacity:${lit || cumulative > 0 ? '1' : '0.5'};${lit ? 'box-shadow:0 0 8px ' + b.color + ';' : ''}"><div style="font-size:34px;filter:${lit ? 'none' : 'grayscale(1)'};">${b.icon}</div><div style="font-size:var(--fs-title);font-weight:700;margin-top:var(--sp-2);color:${lit ? b.color : '#999'};">${b.name}</div><div style="font-size:var(--fs-title);color:var(--text-light);">${b.desc}</div>${habitHtml}<div style="font-size:var(--fs-title);color:var(--text-light);margin-top:var(--sp-2);">日均${b.avg}🍅</div><div style="font-size:var(--fs-title);color:var(--text-light);margin-top:var(--sp-2);">${b.positioning}</div>${progressHint ? `<div style="font-size:var(--fs-title);color:var(--text-light);margin-top:var(--sp-2);">${progressHint}</div>` : ''}<div style="font-size:var(--fs-title);margin-top:var(--sp-2);color:${stateColor};font-weight:${lit ? '700' : '400'};">${stateText}</div><div style="font-size:var(--fs-title);color:var(--text-light);margin-top:var(--sp-2);">累计${cumulative}次</div></div>`;}).join('');renderTimerBadge();}
function renderHabitRemind(){const el=document.getElementById('habitRemindCard');if(!el)return;const habits=appData.habits||[];const undone=(appData.todos||[]).filter(function(t){return!t.done;}).length;const today=getTodayStr();const done=habits.filter(function(h){return(appData.habitLogs[h.id]||[]).includes(today);}).length;const left=habits.length-done;if(left<=0&&undone===0){el.style.display='none';return;}
el.style.display='';let html='';if(habits.length&&left>0){html+='<div style="display:flex;align-items:center;gap:var(--sp-8);background:var(--card);border:2px solid var(--yellow-dark);border-radius:var(--radius-input);padding:var(--sp-8) var(--sp-12);font-size:var(--fs-body);margin-bottom:var(--sp-8);"><span style="font-size:var(--fs-sub);">🌱</span><div style="flex:1;"><b>今日习惯 '+
done+'/'+
habits.length+'</b>，还有 '+
left+' 个没打卡<br><span style="font-size:var(--fs-note);color:var(--text-light);">连续打卡才能养成习惯，点一下就来</span></div><button onclick="goHabitCheck()" style="background:var(--yellow-dark);color:#fff;border:none;border-radius:var(--radius);padding:var(--sp-6) var(--sp-14);font-weight:700;flex-shrink:0;">去打卡 ›</button></div>';}
if(undone>0){html+='<div style="display:flex;align-items:center;gap:var(--sp-8);background:var(--card);border:2px solid var(--blue);border-radius:var(--radius-input);padding:var(--sp-8) var(--sp-12);font-size:var(--fs-body);"><span style="font-size:var(--fs-sub);">📋</span><div style="flex:1;"><b>今日计划还有 '+
undone+' 项未完成</b><br><span style="font-size:var(--fs-note);color:var(--text-light);">未完成的计划明天会继续留着，今天收尾压力更小</span></div><button onclick="goPlanCheck()" style="background:var(--blue);color:#fff;border:none;border-radius:var(--radius);padding:var(--sp-6) var(--sp-14);font-weight:700;flex-shrink:0;">去完成 ›</button></div>';}
el.innerHTML=html;}
