function renderTimerBadge(){const el=document.getElementById('timerBadge');if(!el)return;const currentWeekCount=getWeekHeldTomatoes();let bestIdx=-1,bestState='off';for(let i=WEEKLY_BADGES.length-1;i>=0;i--){const st=getBadgeState(WEEKLY_BADGES[i]);if(st!=='off'){bestIdx=i;bestState=st;break;}}
if(bestIdx<0){el.classList.remove('show');el.innerHTML='';updateHonorEffects();return;}
const bestBadge=WEEKLY_BADGES[bestIdx];let nextBadge=null;for(let i=bestIdx+1;i<WEEKLY_BADGES.length;i++){if(getBadgeState(WEEKLY_BADGES[i])==='off'){nextBadge=WEEKLY_BADGES[i];break;}}
const gloryCls=bestBadge.glow?' badge-glory':'';el.className='timer-badge show'+gloryCls;el.style.borderColor=bestBadge.color;const darkMode=typeof document.body!=='undefined'&&document.body.classList.contains('dark-mode');el.style.background=darkMode?'rgba(24,28,50,.92)':bestBadge.bg;let stateHtml;if(bestState==='carry')stateHtml='<div class="tb-state" style="color: var(--yellow-ink)">⏩ 延续中</div>';else if(nextBadge)stateHtml='<div class="tb-state" style="color: var(--green-ink)">✅ 本周达成</div>';else stateHtml='<div class="tb-state" style="color: var(--green-ink)">👑 本周最高</div>';el.innerHTML=`<div class="tb-icon">${bestBadge.icon}</div><div class="tb-name" style="color:${bestBadge.color};">${bestBadge.name}</div>${stateHtml}`;updateHonorEffects();}
