function reviewDatesWithRecords(){const set={};(appData.records||[]).forEach(function(r){if(!r||!r.startTime)return;set[getDateStr(r.startTime)]=true;});return Object.keys(set).sort().reverse();}
function reviewState(date){const m=appData.reviewStages||{};return m[date]||null;}
