function rvSetYear(key,val){const d=_rv.draft;if(!d)return;if(!d.year)d.year={sat:null,highlights:{},lesson:''};if(key==='sat'){const n=Number(val);d.year.sat=(n>=0&&n<=10)?n:null;renderLifeReview();return;}
d.year[key]=val;}
function rvSetHighlight(m,val){const d=_rv.draft;if(!d)return;const k=String(m);if(!d.year)d.year={sat:null,highlights:{},lesson:''};if(!d.year.highlights)d.year.highlights={};d.year.highlights[k]=val;}
