const dowNames=['周日','周一','周二','周三','周四','周五','周六'];const monthNames=['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];const monthArr=[];for(let m=0;m<12;m++){monthArr.push({m:m,total:monthMap[String(m+1).padStart(2,'0')]||0});}
