const hour=new Date().getHours();let msg;let companionSid=tr.species||'tomato';let st=getTreeStage(tr.points||0);let mood=getTreeMood();let noTomato=tr.lastActiveDate!==today;let noWater=tr.lastWaterDate!==today;if(mood.fade>=0.6){if(noTomato&&noWater){msg='你已经很久没来看我了😢 今天还没完成番茄🍅也没浇水💧，来陪陪我吧~';}else if(noTomato){msg='你今天还没完成番茄呢🍅 我好想陪你一起专注呀~';}else if(noWater){msg='我有点渴了💧 浇浇水我就精神啦~';}else{msg='我有点想你了😟 多来看看我呀~';}}else if(mood.fade>=0.35){if(noTomato&&noWater){msg='今天还没完成番茄🍅也没浇水💧，来一个吧，我陪你~';}else if(noTomato){msg='今天还没完成番茄哦🍅 来一个吧，我陪你~';}else if(noWater){msg='今天还没浇水呢💧 我有点干干的~';}else if(hour<6){msg=pickTalk(TREE_TALKS_TIME.midnight);}else if(hour>=22){msg=pickTalk(TREE_TALKS_TIME.late);}else{msg=randomTreeTalk(companionSid);}}else if(noWater){msg='主人好久没浇水了💧 浇一下我更有精神~';}else if(hour<6){msg=timedTalk(hour,companionSid);}else if(hour<9){msg=timedTalk(hour,companionSid);}else if(st&&(st.name==='种子'||st.name==='嫩芽'||st.name==='幼苗')&&Math.random()<0.5){msg=st.name==='种子'?'我是颗小种子🌱 等你浇水把我唤醒~':st.name==='嫩芽'?'我发芽啦🌿 都是你浇灌的功劳！':'正在努力长高中🌾 你也一起加油呀';}else{msg=timedTalk(hour,companionSid);}
if(_feedThanksLeft>0&&tr.lastFeedDate===getTodayStr()){_feedThanksLeft--;msg=FEED_THANKS_TALKS[Math.floor(Math.random()*FEED_THANKS_TALKS.length)];}
