function _pFont(weight,size){return(weight||700)+' '+size+'px "PingFang SC","Noto Sans SC","Microsoft YaHei",sans-serif';}
function _pEmoji(ctx,emoji,x,y,size,align){ctx.font=size+'px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji","EmojiOne Color","Twemoji Mozilla",sans-serif';ctx.fillStyle='#FFFFFF';ctx.textAlign=align||'center';ctx.textBaseline='middle';ctx.fillText(emoji,x,y);}
function _pBig(n){n=Math.round(n||0);if(n>=10000)return(n/10000).toFixed(1).replace(/\.0$/,'')+'万';if(n>=1000)return(n/1000).toFixed(1).replace(/\.0$/,'')+'千';return String(n);}
function _pScore(v){if(v==null||isNaN(v))return'—';if(v>=9)return'很好';if(v>=7)return'较好';if(v>=5)return'一般';if(v>=3)return'较差';return'很差';}
