function calcExecutionScore(C){const ts=C.taskStats||{planned:0,actual:0,taskCnt:0,doneCnt:0};const activePlan=C.activePlan||0;const activeDone=C.activeDone||0;const parts=[];if(activePlan>0)parts.push({w:0.35,v:activeDone/activePlan,label:'任务',txt:'活跃计划完成 '+activeDone+'/'+activePlan});else if(ts.taskCnt>0)parts.push({w:0.35,v:ts.doneCnt/ts.taskCnt,label:'任务',txt:'任务完成 '+ts.doneCnt+'/'+ts.taskCnt});if(ts.planned>0)parts.push({w:0.3,v:Math.min(1,(ts.actual||0)/ts.planned),label:'计划',txt:'计划🍅达成 '+ts.actual+'/'+ts.planned});const _active=C.activeDays||0;if(_active>0)parts.push({w:0.2,v:Math.min(1,_active/30),label:'执行',txt:'近30天行动 '+_active+' 天'});const _stk=C.streak||0;if(_stk>0)parts.push({w:0.15,v:Math.min(1,_stk/14),label:'稳定',txt:'连续打卡 '+_stk+' 天'});if(!parts.length)return{score:null,grade:'还没数据',sub:'开始专注或制定计划后，这里会展示你的执行力',txt:''};const _wSum=parts.reduce(function(s,p){return s+p.w;},0);const _raw=parts.reduce(function(s,p){return s+p.w*p.v;},0)/_wSum;const score=Math.round(_raw*100);let grade;if(score>=85)grade='🏆 超强执行力';else if(score>=70)grade='💪 执行力在线';else if(score>=50)grade='🌤 执行力一般';else if(score>=30)grade='🌱 执行力待激活';else grade='🪴 才刚刚起步';return{score:score,grade:grade,sub:parts.map(function(p){return p.txt;}).join(' · '),txt:parts.map(function(p){return p.label+' '+Math.round(p.v*100)+'%';}).join(' / ')};}
